// Prepare data for parallel processing
const body = $input.first().json.body;
const text = body.text;
const options = body.options || {
  sentiment: true,
  intent: true,
  entities: true,
  priority: true,
  language: true
};

// API Keys passed from MCP Server
const googleApiKey = body.google_api_key || '';
const openaiApiKey = body.openai_api_key || '';

return {
  json: {
    text: text,
    options: options,
    googleApiKey: googleApiKey,
    openaiApiKey: openaiApiKey,
    startTime: Date.now()
  }
};

// Tag sentiment result
const result = $input.first().json;
return {
  json: {
    source: 'sentiment',
    data: result
  }
};

// Tag entities result
const result = $input.first().json;
return {
  json: {
    source: 'entities',
    data: result
  }
};

// Tag OpenAI result
const result = $input.first().json;
return {
  json: {
    source: 'openai',
    data: result
  }
};

// Merge all tagged results
const items = $input.all();
const prepareData = $('Prepare Data').first().json;
const text = prepareData.text;
const options = prepareData.options;
const startTime = prepareData.startTime;

// Find results by source tag
let sentimentData = null;
let entitiesData = null;
let openaiData = null;

for (const item of items) {
  const source = item.json.source;
  const data = item.json.data;

  if (source === 'sentiment') {
    sentimentData = data;
  } else if (source === 'entities') {
    entitiesData = data;
  } else if (source === 'openai') {
    openaiData = data;
  }
}

// Process sentiment
let sentimentResult = null;
try {
  if (sentimentData && sentimentData.documentSentiment) {
    const ds = sentimentData.documentSentiment;
    sentimentResult = {
      label: ds.score > 0.2 ? 'positive' : ds.score < -0.2 ? 'negative' : 'neutral',
      score: ds.score,
      magnitude: ds.magnitude,
      confidence: Math.min(1, Math.abs(ds.score) + ds.magnitude / 2)
    };
  } else if (sentimentData && sentimentData.error) {
    sentimentResult = { error: sentimentData.error.message || 'Google API error', fallback: true };
  } else {
    sentimentResult = { error: 'No sentiment data', fallback: true };
  }
} catch (e) {
  sentimentResult = { error: 'Sentiment processing failed: ' + e.message, fallback: true };
}

// Process entities
let entitiesResult = [];
try {
  if (entitiesData && entitiesData.entities) {
    entitiesResult = entitiesData.entities.map(e => ({
      type: e.type,
      value: e.name,
      salience: e.salience,
      metadata: e.metadata || {}
    }));
  } else if (entitiesData && entitiesData.error) {
    entitiesResult = [{ error: entitiesData.error.message || 'Google API error' }];
  }
} catch (e) {
  entitiesResult = [{ error: 'Entities processing failed: ' + e.message }];
}

// Process OpenAI (new multi-intent structure)
let intentsResult = [];
let priorityResult = null;
let languageResult = null;

try {
  if (openaiData && openaiData.choices && openaiData.choices[0]) {
    const content = openaiData.choices[0].message.content;
    const parsed = JSON.parse(content);

    // Handle intents array
    intentsResult = parsed.intents || [];

    // Handle priority with new structure
    if (parsed.priority) {
      priorityResult = {
        level: parsed.priority.level || parsed.priority.priority || 'medium',
        score: parsed.priority.score || 0.5,
        indicators: parsed.priority.indicators || [],
        requires_confirmation: parsed.priority.requires_confirmation || false
      };
    }

    // Handle language with new structure
    if (parsed.language) {
      languageResult = {
        code: parsed.language.code || parsed.language.language || 'unknown',
        confidence: parsed.language.confidence || 0
      };
    }
  } else if (openaiData && openaiData.error) {
    intentsResult = [{ error: openaiData.error.message || 'OpenAI API error' }];
  } else {
    intentsResult = [{ error: 'No OpenAI data' }];
  }
} catch (e) {
  intentsResult = [{ type: 'unknown', action: 'unknown', confidence: 0, error: 'OpenAI parsing failed: ' + e.message }];
  priorityResult = { level: 'medium', score: 0.5, indicators: [], requires_confirmation: false };
  languageResult = { code: 'unknown', confidence: 0 };
}

// Build final response
const response = {
  success: true,
  text: text,
  analysis: {}
};

if (options.sentiment !== false) {
  response.analysis.sentiment = sentimentResult;
}

if (options.intent !== false) {
  response.analysis.intents = intentsResult;
}

if (options.entities !== false) {
  response.analysis.entities = entitiesResult;
}

if (options.priority !== false) {
  response.analysis.priority = priorityResult;
}

if (options.language !== false) {
  response.analysis.language = languageResult;
}

response.meta = {
  providers: {
    sentiment: 'google-cloud-nlp',
    entities: 'google-cloud-nlp',
    intents: 'openai-gpt4o-mini',
    priority: 'openai-gpt4o-mini',
    language: 'openai-gpt4o-mini'
  },
  processing_time_ms: Date.now() - startTime
};

return { json: response };
